import 'package:flutter/material.dart';import 'package:sehatak/core/services/health_tracking_service.dart';import 'package:sehatak/presentation/widgets/futuristic/glass_card.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_background.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_app_bar.dart';import 'package:sehatak/presentation/widgets/futuristic/holographic_number.dart';import 'package:sehatak/presentation/widgets/futuristic/futuristic_line_chart.dart';import 'package:sehatak/presentation/widgets/futuristic/glass_bottom_sheet.dart';
class BloodPressureScreen extends StatefulWidget{const BloodPressureScreen({super.key});@override State<BloodPressureScreen> createState()=>_S();}class _S extends State<BloodPressureScreen>{List<double>sys=[],dia=[];final a=TextEditingController(),b=TextEditingController(),p=TextEditingController();@override void initState(){super.initState();_load();}Future<void>_load()async{final r=await HealthTrackingService.history('bloodPressure',days:30);if(mounted)setState((){sys=r.map<double>((e){final s=(e['value']??'').toString().split('/');return double.tryParse(s.first)??0;}).where((e)=>e>0).toList().reversed.toList();dia=r.map<double>((e){final s=(e['value']??'').toString().split('/');return s.length>1?double.tryParse(s[1])??0:0;}).where((e)=>e>0).toList().reversed.toList();});}String get status{final s=sys.isEmpty?0:sys.last,d=dia.isEmpty?0:dia.last;if(s<90||d<60)return'منخفض';if(s<120&&d<80)return'طبيعي';if(s<130&&d<80)return'مرتفع قليلاً';if(s<140||d<90)return'مرتفع';return'مرتفع جداً';}void _add(){showModalBottomSheet(context:context,isScrollControlled:true,backgroundColor:Colors.transparent,builder:(_)=>GlassBottomSheet(title:'إضافة قياس ضغط',child:Column(children:[Row(children:[Expanded(child:TextField(controller:a,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الانقباضي'))),const SizedBox(width:8),Expanded(child:TextField(controller:b,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'الانبساطي')))]),const SizedBox(height:10),TextField(controller:p,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'النبض (اختياري)')),const SizedBox(height:14),SizedBox(width:double.infinity,child:ElevatedButton(onPressed:()async{final s=int.tryParse(a.text),d=int.tryParse(b.text),q=int.tryParse(p.text);if(s==null||d==null)return;await HealthTrackingService.save({'systolic':s,'diastolic':d,'heartRate':q??0,'blood_pressure_at':DateTime.now().toIso8601String()});if(mounted){Navigator.pop(context);_load();}},child:const Text('حفظ')))])));}@override Widget build(BuildContext c){final v=sys.isEmpty?'-- / --':sys.last.round().toString()+' / '+(dia.isEmpty?'--':dia.last.round().toString());return Scaffold(backgroundColor:const Color(0xFF0A0E1A),appBar:FuturisticAppBar(title:'تتبع الضغط',actions:[IconButton(onPressed:_add,icon:const Icon(Icons.add))]),body:FuturisticBackground(glowColor:const Color(0xFFA29BFE),child:ListView(padding:const EdgeInsets.all(16),children:[GlassCard(glowColor:const Color(0xFFA29BFE),child:Column(children:[const Icon(Icons.monitor_heart_rounded,color:Color(0xFFA29BFE),size:52),HolographicNumber(value:v,unit:'mmHg • '+status,color:const Color(0xFFA29BFE),fontSize:58)])),const SizedBox(height:12),GlassCard(child:sys.length>1?FuturisticLineChart(values:sys,color:const Color(0xFFFF3366)):const SizedBox(height:130,child:Center(child:Text('أضف قياسات فعلية لعرض الرسم',style:TextStyle(color:Colors.white54))))) ]));}}
}